class Circle { constructor(r) { this.r = r; } accept(v) { return v.visitCircle(this); } }
class Rect   { constructor(w, h) { this.w = w; this.h = h; } accept(v) { return v.visitRect(this); } }

class AreaVisitor {
  visitCircle(c) { return Math.PI * c.r ** 2; }
  visitRect(r)   { return r.w * r.h; }
}

const area = new Circle(2).accept(new AreaVisitor());
